# Keep the existing screen structure and behavior, but convert its chrome to Material You colors/components.
layout_path = root / 'app/src/main/res/layout/activity_main.xml'
layout = layout_path.read_text()
replacements = {
    'android:background="#080A10"': 'android:background="?attr/colorSurface"',
    'android:paddingStart="22dp"': 'android:paddingStart="20dp"',
    'android:paddingTop="26dp"': 'android:paddingTop="24dp"',
    'android:paddingEnd="22dp"': 'android:paddingEnd="20dp"',
    'android:paddingBottom="150dp"': 'android:paddingBottom="144dp"',
    'android:textColor="#A9C9FF"': 'android:textColor="?attr/colorPrimary"',
    'android:textColor="#FFF9FBFF"': 'android:textColor="?attr/colorOnSurface"',
    'android:textColor="#B9C3D2"': 'android:textColor="?attr/colorOnSurfaceVariant"',
    'android:textColor="#AAB7C9"': 'android:textColor="?attr/colorOnSurfaceVariant"',
    'android:textColor="#D8E6FF"': 'android:textColor="?attr/colorOnSecondaryContainer"',
    'android:textColor="#B7C1D0"': 'android:textColor="?attr/colorOnSurfaceVariant"',
    'android:textColor="#C4CDDA"': 'android:textColor="?attr/colorOnSurfaceVariant"',
    'android:textColor="#94A0B2"': 'android:textColor="?attr/colorOnSurfaceVariant"',
    'android:textSize="32sp"': 'android:textSize="36sp"',
    'android:layout_marginTop="22dp"': 'android:layout_marginTop="20dp"',
}
for old, new in replacements.items():
    layout = layout.replace(old, new)
layout = layout.replace('<Button\n', '<com.google.android.material.button.MaterialButton\n')
layout_path.write_text(layout)

print('Material You UI patch applied')
